@pytest.mark.parametrize(
    "wrap",
    [lambda v: v, lambda v: [v], and_],
    ids=["single", "list", "and"],
)
def test_validator_decorator(self, wrap):
    """
    If _CountingAttr.validator is used as a decorator and there is already
    a decorator set, the decorators are composed using `and_`.
    """

    def v(_, __):
        pass

    a = attr.ib(validator=wrap(v))

    @a.validator
    def v2(self, _, __):
        pass

    assert _AndValidator((v, v2)) == a._validator

@pytest.mark.parametrize(
    "wrap",
    [lambda v: v, lambda v: [v], attr.converters.pipe],
    ids=["single", "list", "pipe"],
)
def test_converter_decorator(self, wrap):
    """
    If _CountingAttr.converter is used as a decorator and there is already
    a decorator set, the decorators are composed using `pipe`.
    """

    def v(_):
        pass

    a = attr.ib(converter=wrap(v))

    @a.converter
    def v2(self, value, field):
        pass

    assert isinstance(a._converter, attr.Converter)
    assert a._converter.takes_self
    assert a._converter.takes_field

def test_validator_decorator_single(self):
    """
    If _CountingAttr.validator is used as a decorator and there is no
    decorator set, the decorated method is used as the validator.
    """
    a = attr.ib()

    @a.validator
    def v():
        pass

    assert v == a._validator
